import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, uv, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const ownedGeometries = [];
  const ownedMaterials = [];
  const ownedTextures = [];
  const timelines = [];
  let disposed = false;

  const makeBasicMaterial = (options = {}) => {
    const material = new MeshBasicNodeMaterial(options);
    ownedMaterials.push(material);
    return material;
  };

  const makePlane = (width, height, material, x = 0, y = 0, z = 0) => {
    const geometry = new PlaneGeometry(width, height);
    ownedGeometries.push(geometry);

    const mesh = new Mesh(geometry, material);
    mesh.position.set(x, y, z);
    root.add(mesh);
    return mesh;
  };

  const backdropMaterial = makeBasicMaterial();
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.02, 0.02, 0.031),
      smoothstep(0.42, 1.0, uv().y)
    ),
    smoothstep(0.0, 1.0, uv().y)
  );
  makePlane(7.2, 6.0, backdropMaterial, 0, 0, -2.5);

  const shadowMaterial = makeBasicMaterial({
    color: '#050509',
    transparent: true,
    opacity: 0.46
  });
  makePlane(2.95, 1.92, shadowMaterial, 0.08, -0.08, -0.16);

  const backingMaterial = makeBasicMaterial({
    color: '#16161d'
  });
  makePlane(2.7, 1.78, backingMaterial, 0, 0, -0.08);

  const imageMaterial = makeBasicMaterial({
    color: '#e8ecf2'
  });
  const imageMesh = makePlane(2.5, 1.5625, imageMaterial, 0, 0.02, 0.08);

  const accentMaterial = makeBasicMaterial({
    color: '#ff2a38'
  });
  makePlane(0.045, 1.18, accentMaterial, 1.31, 0.02, 0.18);
  makePlane(0.72, 0.045, accentMaterial, 0.93, -0.79, 0.18);

  const paperMaterial = makeBasicMaterial({
    color: '#e8ecf2',
    transparent: true,
    opacity: 0.78
  });
  makePlane(0.42, 0.025, paperMaterial, -1.02, 0.82, 0.18);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose();
        return;
      }

      ownedTextures.push(texture);
      if (ctx.THREE.SRGBColorSpace) texture.colorSpace = ctx.THREE.SRGBColorSpace;
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') timeline.kill();
    }

    for (const texture of ownedTextures) texture.dispose();
    for (const material of ownedMaterials) material.dispose();
    for (const geometry of ownedGeometries) geometry.dispose();

    root.userData.handlers = {};
  };

  return root;
}
